"""Attendance with live photo capture.

Rules enforced here (never in the client):
* Timestamps are generated by the server; the client only sends the photo (+ optional location).
* One record per employee per org-local day; duplicate check-in / check-out returns 409.
* Employees act only on their own record; admins see/correct only their own organization's records.
* Corrections need a reason and are stored in attendance_corrections + audit_logs.
* Camera unavailable → employee files an exception request; the admin approves/rejects it.
* Photos live in a private bucket and are served only through short-lived, viewer-bound links.
* Retention: photos older than the org's retention window are purged lazily (no background worker
  needed on serverless) whenever an admin opens the dashboard, or via POST /attendance/retention/run.

Note: a camera photo is evidence for review, not proof of identity or presence. No face recognition.
"""
import csv
import io
import json
from datetime import date, datetime, timedelta
from typing import Literal, Optional
from zoneinfo import ZoneInfo

from fastapi import APIRouter, Depends, File, Form, HTTPException, Query, UploadFile
from fastapi.responses import Response
from pydantic import BaseModel, Field

import db
import storage
from db import W
from links import link, verify
from server import audit, get_org, notify, now, parse_ts, require

router = APIRouter(prefix="/api/attendance")

EMPLOYEE_ROLES = ("org_admin", "finance", "sales_exec")
PHOTO_TYPES = {"image/jpeg": "jpg", "image/jpg": "jpg", "image/png": "png", "image/webp": "webp"}
MAX_PHOTO = 5 * 1024 * 1024
CHECKOUT_WINDOW = timedelta(hours=18)  # an open check-in older than this can no longer be closed by the employee
employee = require(*EMPLOYEE_ROLES)
admin = require("org_admin")


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def local_today(org: dict) -> date:
    return now().astimezone(ZoneInfo(org.get("timezone") or "Asia/Kolkata")).date()


def display_status(rec: dict, today: date) -> str:
    """open = checked in today; incomplete = never checked out on a past day."""
    if rec["status"] == "open":
        return "open" if rec["date"] >= today else "incomplete"
    return rec["status"]


def record_out(rec: dict, viewer: dict, today: date) -> dict:
    photo = lambda which: link(f"/api/attendance/{rec['id']}/photo/{which}", "att", viewer, minutes=30) if rec[f"{which}_photo"] else None  # noqa: E731
    return {k: v for k, v in rec.items() if not k.endswith("_photo")} | {
        "status": display_status(rec, today), "check_in_photo_url": photo("check_in"), "check_out_photo_url": photo("check_out")}


async def read_photo(photo: UploadFile) -> tuple[bytes, str]:
    ctype = (photo.content_type or "").lower()
    if ctype not in PHOTO_TYPES:
        raise HTTPException(400, "Attendance photo must be a JPG, PNG or WEBP image")
    data = await photo.read(MAX_PHOTO + 1)
    if len(data) > MAX_PHOTO:
        raise HTTPException(413, "Photo too large (max 5 MB)")
    if len(data) < 1024:
        raise HTTPException(400, "Photo is empty or unreadable — capture again")
    return data, ("image/jpeg" if ctype == "image/jpg" else ctype)


def coords(org: dict, lat: Optional[float], lng: Optional[float]) -> tuple[Optional[float], Optional[float]]:
    if not org["attendance_location_enabled"] or lat is None or lng is None:
        return None, None
    if not (-90 <= lat <= 90 and -180 <= lng <= 180):
        raise HTTPException(400, "Invalid location")
    return lat, lng


def minutes_between(a: Optional[datetime], b: Optional[datetime]) -> Optional[int]:
    return max(0, int((b - a).total_seconds() // 60)) if a and b else None


async def store_photo(org_id: str, photo: UploadFile) -> str:
    data, ctype = await read_photo(photo)
    try:
        return await storage.put("attendance", org_id, PHOTO_TYPES[ctype], data, ctype)
    except storage.StorageError as e:
        raise HTTPException(e.status, str(e))


async def purge_expired_photos(org: dict) -> int:
    cutoff = local_today(org) - timedelta(days=org["attendance_photo_retention_days"])
    # Fetch-then-update keeps the stored paths so the objects can be deleted from the bucket.
    rows = await db.fetch("select id, check_in_photo, check_out_photo from attendance where org_id = $1 and date < $2 and not photos_purged "
                          "and (check_in_photo is not null or check_out_photo is not null) limit 500", org["id"], cutoff)
    for r in rows:
        for p in (r["check_in_photo"], r["check_out_photo"]):
            if p:
                await storage.delete(p)
    if rows:
        await db.execute("update attendance set check_in_photo = null, check_out_photo = null, photos_purged = true where id = any($1::text[])", [r["id"] for r in rows])
    return len(rows)


# ---------------------------------------------------------------------------
# Employee: own attendance
# ---------------------------------------------------------------------------
@router.get("/me")
async def my_attendance(month: Optional[str] = Query(None, pattern=r"^\d{4}-\d{2}$"), user=Depends(employee)):
    org = await get_org(user["org_id"])
    today = local_today(org)
    start = date.fromisoformat(f"{month}-01") if month else today.replace(day=1)
    end = (start + timedelta(days=32)).replace(day=1)
    recs = await db.fetch("select * from attendance where org_id = $1 and user_id = $2 and date >= $3 and date < $4 order by date desc",
                          user["org_id"], user["id"], start, end)
    today_rec = await db.fetchrow("select * from attendance where org_id = $1 and user_id = $2 and date = $3", user["org_id"], user["id"], today)
    pending = await db.fetch("select * from attendance_exceptions where org_id = $1 and user_id = $2 order by created_at desc limit 10", user["org_id"], user["id"])
    return {"today": today.isoformat(), "record": record_out(today_rec, user, today) if today_rec else None,
            "history": [record_out(r, user, today) for r in recs], "exceptions": pending,
            "location_enabled": org["attendance_location_enabled"], "retention_days": org["attendance_photo_retention_days"]}


@router.post("/check-in")
async def check_in(photo: UploadFile = File(...), capture: str = Form(...), lat: Optional[float] = Form(None), lng: Optional[float] = Form(None),
                   user=Depends(employee)):
    if capture != "camera":
        raise HTTPException(400, "Attendance needs a live camera capture")
    org = await get_org(user["org_id"])
    today = local_today(org)
    if await db.fetchval("select 1 from attendance where org_id = $1 and user_id = $2 and date = $3", user["org_id"], user["id"], today):
        raise HTTPException(409, "You have already checked in today")
    la, ln = coords(org, lat, lng)
    path = await store_photo(org["id"], photo)
    try:
        rec = await db.insert("attendance", {"org_id": org["id"], "user_id": user["id"], "user_name": user["name"], "date": today,
                                             "check_in_at": now(), "check_in_photo": path, "check_in_lat": la, "check_in_lng": ln})
    except Exception as e:  # unique (org,user,date) — a concurrent double submit
        await storage.delete(path)
        if "unique" in str(e).lower() or "duplicate" in str(e).lower():
            raise HTTPException(409, "You have already checked in today")
        raise
    await audit(user, "check_in", "attendance", rec["id"])
    return record_out(rec, user, today)


@router.post("/check-out")
async def check_out(photo: UploadFile = File(...), capture: str = Form(...), lat: Optional[float] = Form(None), lng: Optional[float] = Form(None),
                    user=Depends(employee)):
    if capture != "camera":
        raise HTTPException(400, "Attendance needs a live camera capture")
    org = await get_org(user["org_id"])
    rec = await db.fetchrow("select * from attendance where org_id = $1 and user_id = $2 and status = 'open' order by date desc limit 1", user["org_id"], user["id"])
    if not rec:
        raise HTTPException(409, "No open check-in found. Check in first.")
    if now() - rec["check_in_at"] > CHECKOUT_WINDOW:
        raise HTTPException(409, "Your last check-in is too old to close. Send an exception request to your admin.")
    la, ln = coords(org, lat, lng)
    path = await store_photo(org["id"], photo)
    ts = now()
    row = await db.fetchrow("update attendance set check_out_at = $2, check_out_photo = $3, check_out_lat = $4, check_out_lng = $5, status = 'present', "
                            "duration_minutes = $6, updated_at = $2 where id = $1 and status = 'open' returning *",
                            rec["id"], ts, path, la, ln, minutes_between(rec["check_in_at"], ts))
    if not row:
        await storage.delete(path)
        raise HTTPException(409, "You have already checked out")
    await audit(user, "check_out", "attendance", rec["id"])
    return record_out(row, user, local_today(org))


# ---------------------------------------------------------------------------
# Exceptions (camera blocked / broken)
# ---------------------------------------------------------------------------
class ExceptionIn(BaseModel):
    kind: Literal["check_in", "check_out"]
    reason: str = Field(min_length=5, max_length=500)


class DecisionIn(BaseModel):
    approve: bool
    note: str = Field("", max_length=500)


@router.post("/exceptions")
async def request_exception(body: ExceptionIn, user=Depends(employee)):
    if await db.fetchval("select 1 from attendance_exceptions where org_id = $1 and user_id = $2 and kind = $3 and status = 'pending'",
                         user["org_id"], user["id"], body.kind):
        raise HTTPException(409, "You already have a pending request of this type")
    ex = await db.insert("attendance_exceptions", {"org_id": user["org_id"], "user_id": user["id"], "user_name": user["name"],
                                                   "kind": body.kind, "reason": body.reason.strip()})
    for a in await db.fetch("select id from users where org_id = $1 and role = 'org_admin' and is_active and id <> $2", user["org_id"], user["id"]):
        await notify(user["org_id"], a["id"], "Attendance exception", f"{user['name']}: {body.kind.replace('_', ' ')} — {body.reason.strip()[:80]}", "attendance", "/attendance/admin")
    await audit(user, "exception_request", "attendance", ex["id"], body.kind)
    return ex


@router.get("/exceptions")
async def list_exceptions(status: Optional[Literal["pending", "approved", "rejected"]] = None, user=Depends(admin)):
    w = W().add("org_id = ?", user["org_id"])
    if status:
        w.add("status = ?", status)
    return await db.fetch(f"select * from attendance_exceptions where {w.sql} order by created_at desc limit 200", *w.args)


@router.post("/exceptions/{ex_id}/decide")
async def decide_exception(ex_id: str, body: DecisionIn, user=Depends(admin)):
    org = await get_org(user["org_id"])
    async with db.tx() as c:
        ex = await db.fetchrow("select * from attendance_exceptions where id = $1 and org_id = $2 and status = 'pending' for update", ex_id, user["org_id"], conn=c)
        if not ex:
            raise HTTPException(404, "Request not found or already decided")
        att_id = None
        if body.approve:
            day = ex["requested_at"].astimezone(ZoneInfo(org["timezone"])).date()
            existing = await db.fetchrow("select * from attendance where org_id = $1 and user_id = $2 and date = $3", user["org_id"], ex["user_id"], day, conn=c)
            if ex["kind"] == "check_in":
                if existing:
                    raise HTTPException(409, "This employee already has a check-in for that day")
                att = await db.insert("attendance", {"org_id": org["id"], "user_id": ex["user_id"], "user_name": ex["user_name"], "date": day,
                                                     "check_in_at": ex["requested_at"], "source": "exception"}, conn=c)
            else:
                if not existing or existing["check_out_at"]:
                    raise HTTPException(409, "No open check-in to close for that day")
                att = await db.fetchrow("update attendance set check_out_at = $2, status = 'present', duration_minutes = $3, source = 'exception', updated_at = now() "
                                        "where id = $1 returning *", existing["id"], ex["requested_at"], minutes_between(existing["check_in_at"], ex["requested_at"]), conn=c)
            att_id = att["id"]
        await db.execute("update attendance_exceptions set status = $2, decided_by = $3, decided_at = now(), decision_note = $4, attendance_id = $5 where id = $1",
                         ex_id, "approved" if body.approve else "rejected", user["id"], body.note.strip(), att_id, conn=c)
        await notify(org["id"], ex["user_id"], f"Attendance request {'approved' if body.approve else 'rejected'}",
                     body.note.strip() or ex["kind"].replace("_", " "), "attendance", "/attendance", conn=c)
        await audit(user, "exception_" + ("approve" if body.approve else "reject"), "attendance", ex_id, body.note.strip(), conn=c)
    return {"ok": True}


# ---------------------------------------------------------------------------
# Admin dashboard
# ---------------------------------------------------------------------------
async def employees(org_id: str) -> list[dict]:
    return await db.fetch("select id, name, email, role, is_active from users where org_id = $1 and role = any($2::text[]) order by name", org_id, list(EMPLOYEE_ROLES))


@router.get("/daily")
async def daily(day: Optional[date] = None, user=Depends(admin)):
    org = await get_org(user["org_id"])
    await purge_expired_photos(org)
    today = local_today(org)
    day = day or today
    staff, recs = await employees(org["id"]), await db.fetch("select * from attendance where org_id = $1 and date = $2", org["id"], day)
    by_user = {r["user_id"]: r for r in recs}
    rows = []
    for e in staff:
        r = by_user.get(e["id"])
        if not r and not e["is_active"]:
            continue
        rows.append({"user": e, "record": record_out(r, user, today) if r else None,
                     "status": display_status(r, today) if r else ("absent" if day <= today else "upcoming")})
    counts: dict[str, int] = {}
    for r in rows:
        counts[r["status"]] = counts.get(r["status"], 0) + 1
    pending = await db.fetchval("select count(*) from attendance_exceptions where org_id = $1 and status = 'pending'", org["id"])
    return {"date": day.isoformat(), "today": today.isoformat(), "rows": rows, "counts": counts, "pending_exceptions": pending}


def month_range(month: str) -> tuple[date, date]:
    start = date.fromisoformat(f"{month}-01")
    return start, (start + timedelta(days=32)).replace(day=1)


async def monthly_rows(org: dict, month: str, user_id: Optional[str] = None) -> list[dict]:
    start, end = month_range(month)
    today = local_today(org)
    last = min(end - timedelta(days=1), today)
    workdays = max(0, (last - start).days + 1) if last >= start else 0
    w = W().add("org_id = ?", org["id"]).add("date >= ?", start).add("date < ?", end)
    if user_id:
        w.add("user_id = ?", user_id)
    recs = await db.fetch(f"select * from attendance where {w.sql}", *w.args)
    out = []
    for e in await employees(org["id"]):
        if user_id and e["id"] != user_id:
            continue
        mine = [r for r in recs if r["user_id"] == e["id"]]
        if not mine and not e["is_active"]:
            continue
        st = [display_status(r, today) for r in mine]
        out.append({"user_id": e["id"], "name": e["name"], "role": e["role"], "days_recorded": len(mine),
                    "present": sum(s in ("present", "corrected") for s in st), "incomplete": sum(s == "incomplete" for s in st),
                    "absent": max(0, workdays - len(mine)), "total_minutes": sum(r["duration_minutes"] or 0 for r in mine)})
    return out


@router.get("/monthly")
async def monthly(month: str = Query(..., pattern=r"^\d{4}-\d{2}$"), user=Depends(admin)):
    org = await get_org(user["org_id"])
    return {"month": month, "rows": await monthly_rows(org, month)}


@router.get("/records")
async def records(date_from: Optional[date] = None, date_to: Optional[date] = None, user_id: Optional[str] = None,
                  status: Optional[Literal["open", "present", "corrected", "incomplete"]] = None, user=Depends(admin)):
    org = await get_org(user["org_id"])
    today = local_today(org)
    w = W().add("org_id = ?", org["id"]).add("date >= ?", date_from or today - timedelta(days=30)).add("date <= ?", date_to or today)
    if user_id:
        w.add("user_id = ?", user_id)
    if status == "incomplete":
        w.add("status = 'open'").add("date < ?", today)
    elif status == "open":
        w.add("status = 'open'").add("date >= ?", today)
    elif status:
        w.add("status = ?", status)
    rows = await db.fetch(f"select * from attendance where {w.sql} order by date desc, user_name limit 1000", *w.args)
    return [record_out(r, user, today) for r in rows]


@router.get("/{att_id}/detail")
async def record_detail(att_id: str, user=Depends(admin)):
    org = await get_org(user["org_id"])
    r = await db.fetchrow("select * from attendance where id = $1 and org_id = $2", att_id, org["id"])
    if not r:
        raise HTTPException(404, "Record not found")
    hist = await db.fetch("select * from attendance_corrections where attendance_id = $1 and org_id = $2 order by created_at desc", att_id, org["id"])
    return record_out(r, user, local_today(org)) | {"corrections": [h | {"before": json.loads(h["before"]), "after": json.loads(h["after"])} for h in hist]}


class CorrectionIn(BaseModel):
    check_in_at: Optional[str] = None
    check_out_at: Optional[str] = None
    reason: str = Field(min_length=5, max_length=500)


@router.post("/{att_id}/correct")
async def correct(att_id: str, body: CorrectionIn, user=Depends(admin)):
    org = await get_org(user["org_id"])
    async with db.tx() as c:
        r = await db.fetchrow("select * from attendance where id = $1 and org_id = $2 for update", att_id, org["id"], conn=c)
        if not r:
            raise HTTPException(404, "Record not found")
        cin = parse_ts(body.check_in_at) if body.check_in_at else r["check_in_at"]
        cout = parse_ts(body.check_out_at) if body.check_out_at else r["check_out_at"]
        if not cin:
            raise HTTPException(400, "Check-in time is required")
        if cout and cout <= cin:
            raise HTTPException(400, "Check-out must be after check-in")
        if cout and cout > now() or cin > now():
            raise HTTPException(400, "Times cannot be in the future")
        before = {"check_in_at": r["check_in_at"], "check_out_at": r["check_out_at"], "status": r["status"]}
        after = {"check_in_at": cin, "check_out_at": cout, "status": "corrected" if cout else "open"}
        row = await db.fetchrow("update attendance set check_in_at = $2, check_out_at = $3, status = $4, duration_minutes = $5, updated_at = now() where id = $1 returning *",
                                att_id, cin, cout, after["status"], minutes_between(cin, cout), conn=c)
        await db.insert("attendance_corrections", {"org_id": org["id"], "attendance_id": att_id, "admin_id": user["id"], "admin_name": user["name"],
                                                   "reason": body.reason.strip(), "before": json.dumps(before, default=str), "after": json.dumps(after, default=str)}, conn=c)
        await notify(org["id"], r["user_id"], "Attendance corrected", f"{r['date']}: {body.reason.strip()[:80]}", "attendance", "/attendance", conn=c)
        await audit(user, "correct", "attendance", att_id, body.reason.strip(), conn=c)
    return record_out(row, user, local_today(org))


class SettingsIn(BaseModel):
    location_enabled: Optional[bool] = None
    retention_days: Optional[int] = Field(None, ge=7, le=3650)


@router.get("/settings")
async def get_settings(user=Depends(admin)):
    org = await get_org(user["org_id"])
    return {"location_enabled": org["attendance_location_enabled"], "retention_days": org["attendance_photo_retention_days"],
            "timezone": org["timezone"], "storage": storage.provider()}


@router.patch("/settings")
async def update_settings(body: SettingsIn, user=Depends(admin)):
    upd = {k: v for k, v in {"attendance_location_enabled": body.location_enabled, "attendance_photo_retention_days": body.retention_days}.items() if v is not None}
    if not upd:
        raise HTTPException(400, "Nothing to update")
    await db.update("orgs", W().add("id = ?", user["org_id"]), upd)
    await audit(user, "settings", "attendance", user["org_id"], ", ".join(f"{k}={v}" for k, v in upd.items()))
    return await get_settings(user)


@router.post("/retention/run")
async def run_retention(user=Depends(admin)):
    return {"purged_records": await purge_expired_photos(await get_org(user["org_id"]))}


@router.post("/export-link")
async def export_link(month: str = Query(..., pattern=r"^\d{4}-\d{2}$"), user=Depends(admin)):
    return {"url": link("/api/attendance/export", "att_export", user, minutes=10, o=user["org_id"], m=month)}


@router.get("/export")
async def export(t: str):
    claims = verify(t, "att_export")
    viewer = await db.fetchrow("select * from users where id = $1 and org_id = $2 and role = 'org_admin' and is_active", claims["u"], claims["o"])
    if not viewer:
        raise HTTPException(403, "Not allowed")
    org = await get_org(claims["o"])
    start, end = month_range(claims["m"])
    recs = await db.fetch("select * from attendance where org_id = $1 and date >= $2 and date < $3 order by date, user_name", org["id"], start, end)
    tz, today = ZoneInfo(org["timezone"]), local_today(org)
    fmt = lambda ts: ts.astimezone(tz).strftime("%Y-%m-%d %H:%M") if ts else ""  # noqa: E731
    sio = io.StringIO()
    wr = csv.writer(sio)
    wr.writerow(["Summary", claims["m"]])
    wr.writerow(["Employee", "Role", "Present days", "Incomplete", "Absent", "Total hours"])
    for s in await monthly_rows(org, claims["m"]):
        wr.writerow([s["name"], s["role"], s["present"], s["incomplete"], s["absent"], round(s["total_minutes"] / 60, 1)])
    wr.writerow([])
    wr.writerow(["Date", "Employee", "Check in", "Check out", "Duration (h)", "Status", "Source", "Check-in location", "Check-out location"])
    for r in recs:
        loc = lambda a, b: f"{a:.5f},{b:.5f}" if a is not None and b is not None else ""  # noqa: E731
        wr.writerow([r["date"], r["user_name"], fmt(r["check_in_at"]), fmt(r["check_out_at"]),
                     round(r["duration_minutes"] / 60, 2) if r["duration_minutes"] is not None else "", display_status(r, today), r["source"],
                     loc(r["check_in_lat"], r["check_in_lng"]), loc(r["check_out_lat"], r["check_out_lng"])])
    return Response(("\ufeff" + sio.getvalue()).encode(), media_type="text/csv",
                    headers={"Content-Disposition": f'attachment; filename="attendance-{claims["m"]}.csv"', "Cache-Control": "no-store"})


# ---------------------------------------------------------------------------
# Photo access — viewer-bound link, permission re-checked on every request
# ---------------------------------------------------------------------------
@router.get("/{att_id}/photo/{which}")
async def photo(att_id: str, which: Literal["check_in", "check_out"], t: str):
    claims = verify(t, "att")
    viewer = await db.fetchrow("select id, org_id, role, is_active from users where id = $1", claims.get("u"))
    rec = await db.fetchrow("select * from attendance where id = $1", att_id)
    if not viewer or not viewer["is_active"] or not rec or rec["org_id"] != viewer["org_id"]:
        raise HTTPException(404, "Photo not found")
    if viewer["id"] != rec["user_id"] and viewer["role"] != "org_admin":
        raise HTTPException(403, "Not allowed")
    path = rec[f"{which}_photo"]
    if not path:
        raise HTTPException(404, "Photo not available (removed after the retention period)")
    try:
        return await storage.respond(path, "image/jpeg", f"{which}.jpg")
    except storage.StorageError as e:
        raise HTTPException(e.status, str(e))
